val sweepLabel: String get() = when { isFineSweep -> "Ajuste fino ×0.1"; isFastSweep -> "Barrido rápido ×4"; else -> "Paso normal" }
```

C. Private fields: engineerAgent, focusModeManager, walkieManager.

D. init additions (after btAudioManager init, before initLocalOutput or after refreshAudioOutputs):
```kotlin
// Initialize engineer agent + focus mode + walkie
focusModeManager = FocusModeManager(application)
walkieManager = WalkieTalkieManager(application).also { wm ->
    wm.onAudioChunk = { chunk ->
        val mesh = meshManager ?: return@also
        mesh.broadcastWalkieAudio(mesh.deviceId, chunk, _uiState.value.walkieTargets)
    }
}
meshManager?.onWalkieAudio = { _, chunk -> walkieManager?.playChunk(chunk) }
```
Wait, meshManager is initialized earlier in init. And engineerAgent = EngineerAgent() at field declaration. Also refresh agent advices when mode != OFF periodically — in auto-check loop.

E. Agent methods:
```kotlin
fun setAgentMode(mode: AgentMode) {
    _uiState.update { it.copy(agentMode = mode) }
    if (mode != AgentMode.OFF) refreshAgentAdvices() else _uiState.update { it.copy(agentAdvices = emptyList()) }
}
fun consultAgent() = refreshAgentAdvices()
fun clearAgentAdvices() { _uiState.update { it.copy(agentAdvices = emptyList()) } }
private fun refreshAgentAdvices() {
    val s = _uiState.value
    val snapshot = EngineerAgent.Snapshot(
        isRunning = s.isRunning,
        currentSpl = s.currentSpl,
        safeSplLimit = s.musicianState.safeSplLimit,
        targetSpl = s.config.targetSpl,
        rt60Ms = s.rt60Ms,
        outputs = s.outputs,
        currentDelayMs = s.config.audioDelayMs,
        recommendedDelayMs = s.distanceMeasure.delayMs ?: s.geoInfo.recommendedDelayMs,
        panIsCentered = s.panMatrix.isCentered
    )
    _uiState.update { it.copy(agentAdvices = engineerAgent.advise(snapshot, it.agentMode)) }
}
```

