fun captureDistancePoint() {
    viewModelScope.launch(Dispatchers.IO) {
        val info = locationProvider?.getCurrentLocation() ?: return@launch
        if (!info.hasFix) return@launch
        val point = GpsPoint(info.latitude, info.longitude, info.altitude, info.label)
        _uiState.update { state ->
            val dm = state.distanceMeasure
            when (dm.step) {
                DistanceStep.EMITTER -> state.copy(distanceMeasure = dm.copy(emitter = point, step = DistanceStep.RECEIVER))
                DistanceStep.RECEIVER -> state.copy(distanceMeasure = dm.copy(receiver = point, step = DistanceStep.DONE, speedOfSound = info.speedOfSound))
                DistanceStep.DONE -> state.copy(distanceMeasure = DistanceMeasurement(step = DistanceStep.EMITTER, emitter = point, speedOfSound = info.speedOfSound))
            }
        }
    }
}
fun resetDistanceMeasure() { _uiState.update { it.copy(distanceMeasure = DistanceMeasurement()) } }
fun adjustMeasuredDistance(coarse: Boolean, up: Boolean) {
    val step = if (coarse) 0.5f else 0.01f
    _uiState.update { s ->
        val base = s.distanceMeasure.effectiveDistanceM ?: 0f
        val adjusted = (base + if (up) step else -step).coerceAtLeast(0f)
        s.copy(distanceMeasure = s.distanceMeasure.copy(manualDistanceM = adjusted))
    }
}
fun applyDistanceAutomation() {
    val dm = _uiState.value.distanceMeasure
    val dist = dm.effectiveDistanceM ?: return
    val delay = dm.delayMs ?: return
    val gain = dm.gainCompensationDb ?: 0f
    updateConfig { it.copy(audioDelayMs = delay) }
    _uiState.update { state ->
        state.copy(
            audioDelayMs = delay,
            outputs = state.outputs.map { o ->
                if (o.deviceType == DeviceType.PA_SYSTEM || o.deviceType == DeviceType.CONSOLE || o.deviceType == DeviceType.BLUETOOTH_SPEAKER) o.copy(delayMs = delay) else o
            }
        )
    }
    if (_uiState.value.agentMode != AgentMode.OFF) refreshAgentAdvices()
}
